{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C08", "C22", "C52", "C190", "C191", "C267", "C245", "C270", "C236", "C263", "C286", "C302", "C319"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C08", "C22", "C52", "C190", "C191", "C286", "C302"],
  "claims": [
    {
      "claim": "Disopyramide, the closest structural analog with the same phenyl/2-pyridyl central carbon and a basic amine, has human absolute oral bioavailability of 0.78–0.85 (C08, C22, C52) and essentially complete intestinal absorption (C190, C191), providing direct endpoint evidence that this scaffold exceeds 20% F.",
      "card_ids": ["C08", "C22", "C52", "C190", "C191"]
    },
    {
      "claim": "L6 hepatic records for disopyramide show it is a low hepatic extraction ratio drug (C286); although in vitro hepatocyte turnover was moderate-to-high (C330, C333) and CYP3A4 mediates its N-dealkylation (C297), these in vitro findings did not translate to low human F and are not affirmative threshold-relevant evidence for F < 20%.",
      "card_ids": ["C286", "C330", "C333", "C297"]
    },
    {
      "claim": "The query's 2-pyridyl substitution is associated with slower metabolism than phenyl/phenyl analogs (C302), and a pyridyl/basic-amine analog (triprolidine) was stable in human liver microsomes with t1/2 > 60 min (C319), supporting that the query's scaffold is not high-clearance.",
      "card_ids": ["C302", "C319"]
    },
    {
      "claim": "L5 gut-wall records for close analogs show high permeability without limiting efflux (trihexyphenidyl Papp AB 46.29 × 10^-6 cm/s, ER 0.22, C267/C245; chlorpheniramine no detectable efflux, C270/C236; methadone P-gp inhibition did not reduce bioavailability, C263), supporting the absorption component.",
      "card_ids": ["C267", "C245", "C270", "C236", "C263"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C286", "C302", "C319", "C330", "C333", "C297"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental F measurement exists for the query molecule.",
    "No query-specific hepatic clearance or metabolic stability data are available; L6 records are analog-based.",
    "No formulation, dose, or prandial condition is specified for the query.",
    "Species-specific low F values in L2 are not resolved for the query.",
    "Transfer from disopyramide is structural but not exact; differences in central hydroxyl versus carboxamide and side-chain amine are not directly tested."
  ],
  "decision_summary": "L6 hepatic clearance and metabolic stability records for the closest analog disopyramide indicate low hepatic extraction (C286) despite in vitro turnover (C330/C333), and 2-pyridyl/basic-amine analogs show slower metabolism (C302, C319). Combined with human disopyramide F of 0.78–0.85 and no affirmative threshold-relevant evidence for F < 20%, the prediction remains high with moderate confidence."
}

